// libGDX: the framework walks the actors
stage.act(Gdx.graphics.getDeltaTime());        // calls act(delta) on every actor

// JavaFX: you walk your own collection inside the frame hook
new AnimationTimer() {
    private long prev;
    @Override public void handle(long now) {
        double dt = Math.min((now - prev) / 1e9, 0.25);   // ns -> s, clamped
        prev = now;
        for (Updatable u : entities) u.update(dt);
    }
}.start();
